CREATE TABLE boards (id TEXT PRIMARY KEY NOT NULL, owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, title TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 0, snapshot TEXT NOT NULL CHECK(json_valid(snapshot)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE INDEX boards_owner_updated_idx ON boards(owner_id,deleted_at,updated_at);
INSERT INTO boards(id,owner_id,title,revision,snapshot,created_at,updated_at) SELECT 'legacy-' || owner_id, owner_id, COALESCE((SELECT json_extract(value,'$.title') FROM json_each(board.snapshot) WHERE json_extract(value,'$.id')='root' LIMIT 1),'나의 보드'),revision,snapshot,strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM board;
CREATE TRIGGER board_legacy_insert AFTER INSERT ON board BEGIN INSERT OR IGNORE INTO boards(id,owner_id,title,revision,snapshot,created_at,updated_at) VALUES('legacy-'||NEW.owner_id,NEW.owner_id,COALESCE((SELECT json_extract(value,'$.title') FROM json_each(NEW.snapshot) WHERE json_extract(value,'$.id')='root' LIMIT 1),'나의 보드'),NEW.revision,NEW.snapshot,strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
CREATE TRIGGER board_legacy_update AFTER UPDATE ON board BEGIN UPDATE boards SET title=COALESCE((SELECT json_extract(value,'$.title') FROM json_each(NEW.snapshot) WHERE json_extract(value,'$.id')='root' LIMIT 1),'나의 보드'),snapshot=NEW.snapshot,revision=NEW.revision,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='legacy-'||NEW.owner_id AND revision<NEW.revision AND deleted_at IS NULL; END;
